from collections import deque

def minimal_string(s):
    t = deque()
    u = []

    for char in s:
        if not t or char <= t[-1]:
            t.append(char)
        else:
            while t and char > t[-1]:
                u.append(t.pop())
            t.append(char)

    while t:
        u.append(t.pop())

    return ''.join(u[::-1])

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    s = data[0]
    result = minimal_string(s)
    print(result)
